// Generated by tools/help-index/build.js from src/app/lazy/help/tabs/*.html (E-264).
// Do not edit: change the templates and run `node tools/help-index/build.js`.
export interface HelpIndexEntry { tab: string, heading: string, anchor: string, text: string }

export const HELP_INDEX: readonly HelpIndexEntry[] = [ { "tab": "start", "heading": "Take the tour", "anchor": "take-the-tour", "text": "Take the Tour! It walks you through the app in nine short modules, from a first look with demo data to a busy incident and the paperwork after. It opens in a new tab and works offline. Bookmark it to come back later." },
  { "tab": "start", "heading": "Get set up", "anchor": "get-set-up", "text": "Set up your mission. Open Mission and set the mission name, the operational period, and a default latitude/longitude near your operating area — new reports start from there, which saves typing on every single one. There is no Save button. Mission settings save themselves about a second after you stop typing, and a small note at the top of the page says Saved when they have. Load your roster. Open Rangers and import or add your team. Go to Field Entry. Click the RangerTrak name in the header to get there (it is also the home page). That is where you will spend the incident. The colored dot in the page header tracks those three steps. Hover it for what is still missing; click it to jump to Mission." },
  { "tab": "start", "heading": "Simple view or Full view", "anchor": "simple-view-or-full-view", "text": "Simple view shows the everyday controls. Full view shows every option. Press the Full view button at the top of Entry, Map, Mission or Rangers & Teams to switch: its dot is empty in Simple view and filled plum in Full view. It is one setting for the whole device. In Full view, options that Simple view can hide have a thin plum edge. Anything your mission already uses always shows, and nothing is hidden from your data. Looking for Attach (photos, video and audio on an entry)? It is in Full view (the Full view button at the top of Entry), in any browser. So are From / To stations, the Alternative map and Print map. Simple view hides a control only while your mission has never used it. Once an entry has an attachment, Attach shows in Simple view too, and the same goes for tactical call signs, To stations and message fields. Switching views never changes or deletes anything, and each device keeps its own choice." },
  { "tab": "start", "heading": "Try it with demo data", "anchor": "try-it-with-demo-data", "text": "Want to see the app full of made-up data first? Pick a demonstration here. The Entry page also shows a demo card whenever this device is empty or holds only demo data. While a mission is under way, RangerTrak stays out of your way: no first-run tips, no install prompt, and an update waits as a small Update ready note instead of a Reload bar. Loading a demo then asks you to type the mission name first. The icon at the left of the status pill in the header shows the mode: Demo, Exercise or Incident. Hover it to change it. An Exercise stamps EXERCISE on printed messages, the communications log, the After Action report and the map sheet. In an Exercise, entries that came from the exercise controller show a clapperboard mark in the Origin column. If the controller gave you a scenario time, the header, the Summary and the printed communications log and map sheet show it beside the real time (for example \"Scenario 14 Jan 14:12\"); the times on entries stay real. You can also set it by hand on the Mission page, under Mode. The controller's file of earlier traffic loads with Load catch-up file on the Radio Log page. Instructors: the exercise console at rangertrak.org/exercise/ plays a scenario's traffic for a class to log, with a room display and a debrief. Do this before you need it. RangerTrak works with no Internet — but only once it has loaded at least once on this device. A device that has never opened RangerTrak and has no connection gets nothing. Install it, and open the map for your area, while you still have a signal." },
  { "tab": "start", "heading": "Mission settings worth knowing about", "anchor": "mission-settings-worth-knowing-about", "text": "Most of the rest of the Mission page has a sensible default and can be left alone. These are the ones worth knowing about, because their effect shows up somewhere else. Setting What it changes Coordinate systems shown on Entry Hides formats your team never uses from the entry screen. If a format has gone missing, this is why. Radio log statuses The status buttons on the entry screen, and the marker colors. A status already used by a report cannot be renamed. Google Geocoding API key Optional. Address lookup uses OpenStreetMap by default, free and with no key. Your own Google key switches address lookup to Google, at your own cost. Neither works offline." },
  { "tab": "start", "heading": "Working offline", "anchor": "working-offline", "text": "Works with no Internet Needs a connection Entering and saving reports Looking up a street address All coordinate formats, and Plus Codes Map areas you have not already viewed or saved Roster, report table, export and import Sending feedback Coordinates and Plus Codes are calculated on your device, so they keep working when nothing else does. Addresses have to be looked up. See Maps for saving map coverage ahead of time." },
  { "tab": "start", "heading": "Rangers' phones: how reports reach the command post", "anchor": "field-phones", "text": "A device is set up one of two ways. The full app is for the command post scribe: every page, the roster, the maps and the mission settings. Field mode is for a ranger's own phone, to file their own reports. It shows only Entry and Help - AAR (after-action review) notes have no menu item on either device, but the AAR/214 button ( AAR note in field mode) at the top of the page still works in field mode, and its dialog's See all notes link reaches the notes page from there too. On a brand-new phone or tablet the welcome panel offers field mode; on a laptop it is under Mission > Advanced > Field phone . Either way it is only offered on a brand-new device. To go back to the full app, use Leave field mode in the menu, or Turn off field mode , which appears here on a field-mode device. This device is in field mode. Turn off field mode RangerTrak never sends a report over the network by itself. Every report is saved on the phone the moment it is submitted, with or without a signal. Sending is a separate step: On the phone, Send my reports (above the Entry form) puts every report on the phone into one small file and opens the phone's share sheet. Photos, audio and video attached to a report go in the same share, next to the file. The top of the phone's screen counts its reports and how many are not sent yet. The ranger picks the route: email or a messaging app over cell data or WiFi , or AirDrop / Quick Share to a station device close by. With no signal, send it later. Nothing is lost by waiting. At the command post, Load Report Packet on the Radio Log page merges the file in. Reports already in the log are skipped, so sending the same file twice does no harm. If some reports are dated before this mission started, or in the future, it asks first: that is usually an old packet, or a phone whose clock is wrong. Pick the photos and other files together with the packet file. Each is checked against the report it belongs to; any that don't match are not stored. If a phone's share sheet can't take the photos along (too big), the packet goes alone and the app says so: send the photos separately, or use a hand-over file. No data at all? Read the report over the radio and the scribe types it in, as always. That is also the right choice for anything urgent or needing a reply: the phone's Online/Offline badge only says the phone has some connection, not that a report arrived, and the phone gets no receipt when it is merged. Install first. Install RangerTrak on the phone from rangertrak.org before heading out. That one visit needs the Internet; after it, entering reports works offline. RangerTrak Board is not a third kind of device. It is an optional extra on the command post's full app (Mission page): the station publishes a read-only copy of the log, without the roster, to the RangerTrak Board program on a laptop on its own WiFi or hotspot, so people on that network can watch it in a browser. Reports still only go into the log at the command post; phones cannot send reports through it." },
  { "tab": "start", "heading": "Mission's Data safety card and Danger zone", "anchor": "mission-s-data-safety-card-and-danger-zone", "text": "At the bottom of the Mission page, the Data safety card holds: Request persistent storage — ask the browser not to discard your mission when it is short of space. Accept if offered. On iPhone and iPad (every browser) and in Safari on a Mac this is not reliable, and data can be cleared after about a week unused — install RangerTrak and back up. Back up mission — the whole mission in one file (plus a second file for any attachments), for backup or handover to another device. It offers an optional passphrase that encrypts the file. Below it, the collapsed Danger zone holds: Reset mission to defaults — back to defaults, at the start of a new incident. Restore mission — load a file made by Back up mission . Load sample mission — a ready-made demonstration mission, for training or showing someone the app. Pick one from Demo scenario first. Field Entry also shows a demo card, and Help → Start has a Load a demo button, whenever the device is empty or holds only demo data. In a mission that is under way, loading a demo asks you to type the mission name first. Load sample mission , Restore mission and Reset mission to defaults all replace what is on this device. Back up first if you need to keep it. On iPhone or iPad: an installed RangerTrak (added to the Home Screen) keeps its own storage, separate from Safari's. If you set up a mission in a Safari tab first, it will not appear once you install the app. Install RangerTrak before setting up a mission — or if you already set up in Safari, use Back up mission there, then Restore mission in the installed app." },
  { "tab": "faq", "heading": "Frequently asked", "anchor": "frequently-asked", "text": "" },
  { "tab": "faq", "heading": "Do I need an account, a login, or an API key?", "anchor": "do-i-need-an-account-a-login-or-an-api-key", "text": "No. Everything RangerTrak does to enter, convert, map, export and back up reports works with no account and no key. The one exception is optional: you may supply your own Google key on the Mission page to use Google for address lookup instead of the free OpenStreetMap default. Nothing requires it." },
  { "tab": "faq", "heading": "What is a \"Ranger\"?", "anchor": "what-is-a-ranger", "text": "Anyone on your team who reports in by radio: a CERT member, a searcher, an ARES or ham operator, a volunteer at a post. RangerTrak calls them all rangers. Each one may have an FCC call sign and, if your agency issues one, a Ranger ID ; the Mission page lets you rename that ID to what your agency calls it. Names for positions and teams, such as \"Gate 3\" or \"Vashon EOC\", are tactical call signs : list them on the Mission page, pick who is operating each one, and choose them on Entry in the From or To station box. The operator’s call sign is filled in for you, and left blank if they do not have one." },
  { "tab": "faq", "heading": "Will it work with no Internet?", "anchor": "will-it-work-with-no-internet", "text": "Yes, if it has been loaded on this device at least once, and you saved map coverage for your area beforehand. A device that has never opened RangerTrak needs a connection to get started." },
  { "tab": "faq", "heading": "Do I have to press Save?", "anchor": "do-i-have-to-press-save", "text": "No. The Mission page saves your changes by itself about a second after you stop typing, and says Saved at the top when it has. On the Rangers and Radio Log pages, edits typed into the grid save themselves as soon as you leave the cell. If a Mission value is outside what is allowed (a latitude past 90, say), the page says Not saved yet and saves as soon as you fix it." },
  { "tab": "faq", "heading": "A coordinate format disappeared from the entry screen.", "anchor": "a-coordinate-format-disappeared-from-the-entry-screen", "text": "It has been switched off for this mission, under Mission → Location Defaults . The Show all coordinate systems toggle on the entry screen brings them back for this session." },
  { "tab": "faq", "heading": "What happened to What3Words?", "anchor": "what-happened-to-what3words", "text": "It's shelved pending a rewrite against a newer version of their service, so it isn't offered anywhere in the app right now. Plus Codes do the same job and are calculated on your device, so they keep working with no connection." },
  { "tab": "faq", "heading": "What do the marker shapes and the lines mean?", "anchor": "what-do-the-marker-shapes-and-the-lines-mean", "text": "Each ranger gets their own marker shape and color, from their call sign, so they look the same everywhere. Lines join one ranger's reports oldest to newest, and the label shows how long ago the most recent one came in." },
  { "tab": "faq", "heading": "Why can't I save the satellite map for offline use?", "anchor": "why-can-t-i-save-the-satellite-map-for-offline-use", "text": "Each map comes from a different provider, and their rules decide what may be saved on your device, not RangerTrak. Esri's satellite imagery, hillshade and roads-and-places layers, OpenStreetMap and the hiking trails layer are online only, because their providers don't allow saving their maps in bulk. OpenTopoMap can be saved anywhere. In the United States, the USGS aerial photos (a base map) and USGS shaded relief (an overlay) are free government maps that can be saved too. Aerial photos take roughly twice the space of the same area on OpenTopoMap; Save this area shows the size before it saves anything." },
  { "tab": "faq", "heading": "How do I thin out a crowded map?", "anchor": "how-do-i-thin-out-a-crowded-map", "text": "In the layers box (top right of the map), untick Places, Radio log entries or Ranger paths. Under the map, Show can narrow the entries to the Latest per ranger, or to those that Need attention (the statuses ticked Flag on map on the Mission page). With Ranger paths on, All and Need attention draw each ranger's full trail; Latest per ranger shows one point each, so no trails. A strip along the top of the map lists whatever is hidden, each with an x, and Show everything brings it all back. The map starts with everything shown each time, and a printed map says \"Filtered:\" in its title box when anything is hidden." },
  { "tab": "faq", "heading": "How do I put a list of places on the map, or hand one on?", "anchor": "how-do-i-put-a-list-of-places-on-the-map-or-hand-one-on", "text": "On the Map page, open Import, export & print near the bottom and choose Import places . It reads an Excel or CSV list, a Google My Maps export (Menu, Export to KML or KMZ; each My Maps layer becomes a category) or a GeoJSON file. You see what would be added or updated before anything changes, and nothing is ever deleted. Rows without a latitude and longitude are skipped, because addresses are not looked up. To hand places on, tick the categories you want under Export places and choose Spreadsheet, CSV or Setup file." },
  { "tab": "faq", "heading": "A newer version of my list came in. How do I drop the people who left it?", "anchor": "a-newer-version-of-my-list-came-in-how-do-i-drop-the-people", "text": "Give the import a Layer name (a spreadsheet suggests one from its file name). The next time you import a list under the same name, RangerTrak asks, for example, “2 people are no longer in Fernhollow CERT. Remove them?” It starts at No. Yes removes only those people, and only if no other list also has them; anyone you added by hand is never offered. The same works for places on the Map page. Radio log entries that name a removed person keep the call sign as it was written. Layers on this device , in the same panel, lists what the device remembers and has Remove this layer ." },
  { "tab": "faq", "heading": "What does Print map give me?", "anchor": "what-does-print-map-give-me", "text": "A one-page landscape map sheet you can hand out or pin up. The map fills the whole page, with a north arrow, a scale bar, the map credit and latitude/longitude marks around its edge (on the standard map, in the format picked under the map). A title box (the mission, the operational period and the time it was printed) and a legend box (the markers, the teams, the named places and the check-in shading) sit on top of the map, in whichever spot hides none of your markers. On a very crowded map there may be no such spot: the title then goes in a line above the map, and the legend prints whole at the top of a second page. Range rings around the command post always print, even if they are switched off on screen. Reports at nearly the same spot fan out around that spot, each joined to it by a thin line, so every one can be read. Each report's \"minutes since\" number sits on that report's marker. Every report is its own marker, not grouped into numbered bubbles, so if you print to PDF you can zoom in to see them. Print map takes a few seconds (\"Preparing the map...\") to load a more detailed map for paper. Online it fetches it; offline it uses the area you saved for offline use, which already includes two closer zoom levels, so print at about the zoom you saved at. If some of that detail isn't saved, it prints the map as it looks on screen rather than leaving blank patches. Use the Print map button rather than your browser's own Print command, which skips that step. There is a line at the bottom to sign as the person who prepared it." },
  { "tab": "faq", "heading": "Installing on a phone: how browsers differ", "anchor": "installing-on-a-phone-how-browsers-differ", "text": "Chrome, Edge, Samsung Internet: open rangertrak.org, then the browser menu, Add to Home screen , and choose Install (not \"Create shortcut\"). The app then opens in its own window, and Back from its first page closes it. Chrome's \"Download\" button is not installing: it saves a still copy of the page for reading (\"Viewing an offline copy of this page\"), in which the app doesn't work. Close it and install as above. Firefox for Android: the home-screen RangerTrak opens as an ordinary Firefox tab. Pressing Back from the app's first page shows a blank Firefox screen with no menu; that is Firefox's empty tab, not RangerTrak, and your data is untouched. Use the app's own menu to move between pages, or install from one of the browsers above for a true app window. \"RangerTrak is already open\": only one copy of the app may edit your data at a time, so an older RangerTrak tab still open in the same browser brings this up. Switch to that one, or press Use this tab instead . The keyboard: on phones and tablets the radio log entry page no longer opens the on-screen keyboard by itself; tap a box when you're ready to type. (With the keyboard open, Android's Back closes the keyboard first.)" },
  { "tab": "faq", "heading": "There's no Install button. How do I install anyway?", "anchor": "there-s-no-install-button-how-do-i-install-anyway", "text": "The Install button shows only when your browser offers to install the app, and RangerTrak holds it back while a mission is under way. You can still install from the browser itself: During a mission: in Chrome or Edge, use the install icon at the right of the address bar, or the browser menu ( Install RangerTrak , or Cast, save and share then Install page as app ). On an Android phone, use the menu, Add to Home screen , then Install . Already installed: there is nothing to do. Open RangerTrak from its icon rather than a browser tab. iPhone or iPad: there is never a button. Tap Share , then Add to Home Screen . Do this before you set up a mission: the installed app does not see what you did in the browser tab. Safari on a Mac: choose File , then Add to Dock . Firefox on a computer: it does not install web apps. Install from Chrome or Edge, or keep using the Firefox tab and back up the mission often. Opened from a link in an email, chat or social app: that app's own built-in browser can't install. Use its menu to open the page in your real browser. Private or incognito window: it can't install, and everything is wiped when the window closes. Open rangertrak.org in an ordinary window." },
  { "tab": "faq", "heading": "I pressed Print but it saved a PDF instead.", "anchor": "i-pressed-print-but-it-saved-a-pdf-instead", "text": "Every Print button opens your browser's own print dialog, and the browser starts on the last place you printed to, which is often \"Save as PDF\". Choose your printer there once; the browser remembers it, so from then on it is Print, then Enter. If you only see a box asking for a file name, your browser saved the ICS-213 as a file instead: open that file and print it. In Chrome or Edge you can make it print directly by setting the browser to open PDFs rather than download them (Settings, Privacy and security, Site settings, PDF documents). Firefox always saves the file. On a laptop kept just for RangerTrak, starting Chrome or Edge with --kiosk-printing in its desktop shortcut skips the print dialog entirely and prints straight to the default printer. To print more than one copy of an ICS-213, set Copies beside the Print button on the Messages page; for automatic printing, set Extra copies for the paper log on the Mission page (it is saved with the mission)." },
  { "tab": "faq", "heading": "The Radio Log page looks different on my phone.", "anchor": "the-radio-log-page-looks-different-on-my-phone", "text": "On a phone it becomes a read-only list of cards, because the full table cannot be used accurately at that width. Corrections need a wider screen." },
  { "tab": "faq", "heading": "How do I get the roster onto another device?", "anchor": "how-do-i-get-the-roster-onto-another-device", "text": "Export roster on the Rangers page, then Import a list on the other device. To start from a spreadsheet instead, use Import a list with an Excel or CSV file; the Rangers page also has a blank template. That moves only the roster. To move a whole mission, use Back up mission on the Mission page instead." },
  { "tab": "faq", "heading": "A new version appeared. Is it safe to reload mid-mission?", "anchor": "a-new-version-appeared-is-it-safe-to-reload-mid-mission", "text": "Yes. Reports are already saved on the device, not held in the page, so reloading takes a few seconds and loses nothing." },
  { "tab": "faq", "heading": "Can other people see my data?", "anchor": "can-other-people-see-my-data", "text": "Only if they have this device — with two exceptions. Anything sent through the feedback form becomes a public issue, so keep mission data out of it. And if you turn on Send this log to a RangerTrak Board yourself (on the Mission page, off by default), report content — never the roster — goes to a server on your own WiFi/hotspot for others on that same network to read. See Your data and the Mission page's own Help button for the full detail." },
  { "tab": "faq", "heading": "Can several people watch the same log at once?", "anchor": "rangertrak-board", "text": "Yes — turn on publishing in the Mission page's RangerTrak Board card. Run the RangerTrak Board program on a laptop at the command post, which can be the scribe's own (download the RangerTrak Board kit from the latest release on GitHub, unzip it and double-click Start RangerTrak Board ); it prints an address on startup. Anyone on the same WiFi/hotspot can open that address (with /view added, or by scanning the QR code it shows) to see a live, read-only comms log, each with their own filter and sort. A second tab lists the ICS-213 messages, with their To, Subject and Message, and opens each one to read or print. It's a separate view, not shared editing — reports are still only ever entered on the device actually filing them. You can set a viewers' password on the same card, and photos can be shown there too if you switch that on." },
  { "tab": "faq", "heading": "The Board won't connect. What do the messages mean?", "anchor": "board-wont-connect", "text": "On the Mission page's RangerTrak Board card, press Test connection . It asks the Board to say hello and names the most likely reason in one sentence. These are best guesses, because a browser can't see exactly why a connection failed. The usual ones: this device isn't on a network; it is on a different Wi-Fi from the Board laptop (check the Wi-Fi name in the Board laptop's window); the browser hasn't accepted the Board's certificate yet (press Open the Board , choose Advanced, then Proceed, and come back); the browser is blocking access to devices on this network (allow local network access for this site in the browser's site settings); or something answered that isn't a RangerTrak Board. Details holds the technical line for whoever is helping. On a viewer's screen, lost means that viewer can't reach the Board. The last reports stay on screen, and it says when it lost the Board and asks whether the Board laptop is awake. Scribe quiet means the Board is fine, but the scribe's device hasn't checked in for over 2 minutes, so the log may be out of date." },
  { "tab": "after", "heading": "Starting a device over", "anchor": "starting-a-device-over", "text": "Back up first: none of this can be undone. Loading a demo, Start a real mission and Delete radio log entries and messages each show a What to clear list before they do anything: A demo or a real mission replaces the whole mission. The roster, ranger photos, radio log (with its attachments), places and settings always go. Notes about this mission, ICS-214 lines and the ICS-214 header start ticked; untick any you want to keep. Notes about RangerTrak start unticked. Deleting the radio log clears only the log and its attachments. Everything else starts unticked. The list has Back up mission first . During a live mission you also type the mission name before it goes ahead. For a full reset, also use Delete all rangers on the Rangers page and Reset mission to defaults under Mission → Danger zone . Load sample mission , Restore mission and Reset mission to defaults all replace what is on this device. Back up first if you need to keep it. See Your data for what a mission's data actually is and where it lives." },
  { "tab": "after", "heading": "After-action notes", "anchor": "after-action-notes", "text": "During the mission, AAR/214 (AAR: after-action review) at the top of every page records something to fix or improve later, without leaving the page you are on. At the top of the box, choose Mission for a note about this mission or RangerTrak for one about the app itself. The same button adds a line to your ICS-214 activity log : what you did or what changed at your position, such as arriving, a shift change or a radio that stopped working. A 214 line is not a radio call, so it does not go in the radio log. Choose ICS-214 at the top of the box; the time is now unless you change it, which is handy when you write things down late. On the AAR notes page, the ICS-214 section lists the lines, and Export ICS-214 fills in FEMA's own ICS-214 form from them, ready to print and sign. At the debrief, open AAR notes . Give each note an area, a recommendation and an owner. Print produces an improvement-plan table of the incident notes, and Export downloads every note as a spreadsheet. Notes about RangerTrak can go to its developers through Review and send , which opens the Feedback form so you can check them first." },
  { "tab": "after", "heading": "Mission summary", "anchor": "mission-summary", "text": "Current summary , on the AAR notes page and the Radio Log page, shows where the mission stands: how many messages came in each hour, which teams, stations and operators they came from, the entries that need attention, and your AAR notes grouped by area. Choose this operational period, the whole log, or dates of your own. You can run it at any time: at the end of a period, at the end of the mission, or just to see how things are going. It only reads the radio log, so it never stops logging and nothing is closed or locked. Running it later simply gives a newer summary. Print and Export make the record of that moment. Each is stamped with the mission, the period it covers, and when it was made, so bring the printout to the after-action review. Nothing is saved on the device, so print or export it if you want to keep it. Notes are part of Back up mission . Deleting the radio log leaves them alone; delete them on the AAR notes page when you no longer need them. AAR notes and Feedback are different things. An AAR note stays private on this device, for your own team's debrief. Feedback ( Help → Contact us ) goes straight to RangerTrak's developers as a public GitHub issue - only a note marked RangerTrak can be passed to it, through Review and send , and only after you check it there." },
  { "tab": "after", "heading": "What to keep, what to clear", "anchor": "what-to-keep-what-to-clear", "text": "After the mission Do this Keep a record of what happened Back up mission &ngsp; (Mission → Data safety) before clearing anything — settings, roster and reports in one file Clear reports for the next mission Radio Log → Delete radio log entries and messages ; in its What to clear list, tick notes or 214 lines only if they should go too Reuse the same roster next time Leave the roster alone — it is not tied to a single mission and does not need to be re-imported Start completely fresh Start a real mission on Entry clears the roster, log, places and settings in one step; or clear them one at a time as above The roster holds participant personal data. If this device is being handed off, reused for another purpose, or is not yours, clear the roster too — see Your data for why it is confidential." },
  { "tab": "after", "heading": "Uninstalling RangerTrak", "anchor": "uninstalling-rangertrak", "text": "Uninstalling the app doesn't always delete its data. On iPhone and iPad, removing it does. On a computer, Chrome and Edge ask you first. On Android it varies by device. To be sure, back up what you need, then clear the site data for rangertrak.org before uninstalling. See the \"Deleting your data\" section of RangerTrak's privacy policy for detail." },
  { "tab": "data", "heading": "Where your data is", "anchor": "where-your-data-is", "text": "See RangerTrak's privacy policy for the full picture. The short version is below. In this browser, on this device. Not on a server, not in an account, not shared with the other devices your team is using. Each browser on each device keeps its own separate copy. That is what lets RangerTrak work with no connection. It also means the device is the only copy, so back it up." },
  { "tab": "data", "heading": "Handing a mission to another scribe", "anchor": "hand-over", "text": "When another scribe, or the next shift, already has entries of their own on their device, use Hand over to another scribe on the Radio Log page. Hand over saves one file with the people, the places and every radio log entry. On the other device, Merge in shows what the file would add or change before anything happens, then merges it. Nothing there is replaced or removed, and merging the same file twice changes nothing. The file holds people's names and phone numbers. Type a passphrase to lock it; leave the box blank and it is not locked. A forgotten passphrase cannot be recovered. For a blank device, use Restore on the Mission page instead. Trying it out with a demo? If both devices loaded the same demo, they share the people and places, but each device's demo entries are new to the other, so the merge adds them all and the log looks like doubled traffic. That is expected: hand over from a device with a demo to one without, or start the second device blank." },
  { "tab": "data", "heading": "Restored the wrong file? Undo last import", "anchor": "undo-import", "text": "Before Restore , a Report Packet import, a Setup file or a roster import ( Rangers > Import a list), RangerTrak keeps a safety copy of everything on this device for 24 hours. Until then, Mission > Data safety shows Undo last import , which puts the mission back exactly as it was just before. After a roster import it puts back only the roster and ranger photos, so nothing you logged since is lost; the same button shows on the Rangers page. It also works after a merge, and puts back the whole mission, so anything logged since goes too (Undo says how many entries, and offers a backup first). Discard safety copy throws it away early. There is only one: the next import replaces it. The copy holds the whole roster and is locked with the rest if device encryption is on. While it exists, the photos it refers to are kept; that space comes back when it expires or is discarded. Restore also shows a preview first: what is on this device and what is in the file, side by side, including how many entries here are not in the file and will be replaced. Cancel is the default." },
  { "tab": "data", "heading": "Photos, video and audio on entries", "anchor": "attachments", "text": "Attach on the Entry page, or Add in the viewer of a saved entry, keeps a file with the entry. The original is stored exactly as it arrived, with a fingerprint (SHA-256) so a later copy can be shown to be unaltered. The viewer shows the fingerprint in short form, with a copy button. Attach is under the Notes box on the Entry page, in any browser. Attach is in Full view (the Full view button at the top of the page), in any browser. Once the mission has an attachment it shows in Simple view too. Originals keep their hidden details , including the GPS position a phone wrote into a photo. The thumbnails shown in lists and printouts do not. Think before sharing an original outside the team. An iPhone may convert a HEIC photo to JPEG before RangerTrak sees it. What RangerTrak fingerprints is what it was given. Files take space on this device. Mission > Data safety shows how much of the mission's attachment budget is used and lets you change it. RangerTrak warns at 80% and 100%, and asks before a file over 100 MB, but only the browser's own limit can stop you. Back up mission saves an attachments file next to the backup (locked with the same passphrase). Restore accepts the backup, the attachments file or both, and refuses any file that does not match its fingerprint. A hand-over carries the attachments too." },
  { "tab": "data", "heading": "One copy per browser", "anchor": "one-copy-per-browser", "text": "Each browser keeps its own copy, and the copies never sync. Chrome and Edge on the same laptop are two separate RangerTraks. Only one tab or window at a time. If RangerTrak is open elsewhere in the same browser, a second tab says RangerTrak is already open and does not save. On iPhone and iPad, RangerTrak added to the Home Screen is a separate copy from the one in Safari (see Getting started ). To run two missions at once, use two browsers, or two profiles in one browser. Give the missions different names, so a Report Packet opened in the wrong one is flagged. Only one of them should publish to a given RangerTrak Board, which shows whichever log reached it last. Never use a private or incognito window. Everything in it is erased when it closes. rangertrak.org counts page loads with Cloudflare's cookie-free analytics — no cookies, and nothing you type. Your mission stays on this device. When online, the app fetches map images and looks up addresses for report locations — that happens automatically, not only when you choose to look one up. Sending feedback, and turning on RangerTrak Board publishing, are the two things that only happen if you choose to." },
  { "tab": "data", "heading": "The roster is confidential", "anchor": "the-roster-is-confidential", "text": "The roster holds legal names, personal phone numbers, and call signs that tie each row to a publicly searchable license record. It is stored unencrypted on the device, unless you turn on device encryption on the Mission page (Data safety > Device encryption) - which also covers radio log entries, after-action notes, ranger photos and attachments, and needs a passphrase that cannot be recovered if lost. Rangers' own Export roster and Export changes , and every spreadsheet export, are plain-text files regardless. Back up mission on the Mission page is the one exception among exports: it includes the roster, and it offers an optional passphrase - leave it blank and it's the same plain file as before, type one and the file is encrypted. Share exports only with people who need them for this mission, and delete them when the mission is over. Given a callsign, the FCC's own public licensee lookup already shows more than this roster does - legal name and mailing address for any licensed amateur radio operator. This app does not meaningfully add to that public exposure, with one exception: photographs, which are not part of any public record." },
  { "tab": "data", "heading": "Getting data off the device", "anchor": "getting-data-off-the-device", "text": "Back up mission on the Mission page is the one to reach for by default — it round-trips everything (settings, roster and reports) back in on another device, so it doubles as the actual backup. It includes ranger photos, and your Google geocoding key only if you protect the backup with a passphrase. Export roster on the Rangers page moves just the roster, as a spreadsheet that Import a list reads straight back in. Export changes , beside it, is for after an event: it saves only the rangers added or edited on this device since the roster was imported, so whoever keeps the master list can add the walk-ups and fixes without combing through the whole roster. The Setup file card on the Mission page (under Data safety) is different from both: it packages any combination of roster, photos, places and settings — but never radio log entries — for setting up a NEW device before a mission starts, merging into whatever is already there rather than replacing it (Export roster never includes photos; Back up mission is a mid/post-mission backup that assumes reports already exist and always replaces wholesale). Print roster on Rangers and Print places on the Map page print the same lists on paper, grouped by team and by category (the roster sheet carries names and phone numbers, so keep it safe). Export on Radio Log produces an Excel-friendly spreadsheet — useful for working with the data, but one-way: it cannot be imported back in. Ranger photographs stay on the device they were added to. They are never uploaded. Name each file after the ranger's id or callsign - any common image format works." },
  { "tab": "data", "heading": "Make a map file for your area", "anchor": "map-file-help", "text": "The Alternative map on the Map page shows the whole world in low detail. For street-level detail where you work, make a map file for your area once, while you have a good connection, and load it onto each device. Get the free pmtiles tool from its release page (pick the file for your computer). On the Map page, turn on Use MapLibre + PMTiles Map and move the map so it shows your area. Open Get a map file for this area and press Copy command . Paste the command into a terminal (Command Prompt on Windows) and replace YYYYMMDD with a recent date from maps.protomaps.com/builds . Run it. It saves my-area.pmtiles , usually a few megabytes for a town. Back on the Map page, press Load a custom .pmtiles file… and pick that file. Do this on every device that needs the map." },
  { "tab": "data", "heading": "Starting a device over", "anchor": "starting-a-device-over", "text": "See the After mission tab for what to export, clear or reset once an operational period ends." },
  { "tab": "data", "heading": "Reporting a problem", "anchor": "reporting-a-problem", "text": "The Log page records what the app did this session. On the Contact us tab, tick Include a diagnostic report on the feedback form — it is far more useful than a description of what went wrong. The log is cleared when you reload, so copy or export it before reloading. It is a raw diagnostic record and can contain report details, addresses and call signs, so treat it as confidential. There is a feedback form on the Contact us tab. Anything sent through it becomes a public issue on the project's repository, so keep mission data out of it - or email the maintainer privately instead, from the same tab." },
  { "tab": "about", "heading": "What RangerTrak is", "anchor": "what-rangertrak-is", "text": "A log of who is where, when, and in what condition , for teams reachable only by voice radio. Field teams radio in; you transcribe; RangerTrak maps it and keeps the record. It runs entirely in this browser, on this device. No server, no account, no login. Your mission stays on this device. When online, the app fetches map images and looks up addresses for report locations. See RangerTrak's privacy policy for the full picture." },
  { "tab": "about", "heading": "Two phases, even when one person does both", "anchor": "two-phases-even-when-one-person-does-both", "text": "Setup is infrequent and considered — Mission and Rangers, before or between operational periods. Entry is repetitive and time-critical — the entry screen, while reports come in. The app is built around the second one being fast. RangerTrak is made by SteadyEOC: one person building tools for emergency teams that have to keep working when the network doesn't. RangerTrak is free and open source (AGPL), so any team can run it, adapt it, and keep using it for as long as they need. There's no licence to renew and no vendor to outlive. More at rangertrak.com . To report a problem or suggest something , see the Contact us tab. A Progressive Web App: installable, and runs with no Internet once loaded Angular 22 with TypeScript, signals, zoneless change detection, and Material Design Leaflet maps with marker clustering, an overview map, and offline tile saving MapLibre GL + PMTiles: a vector map with basemap data bundled into the app Address lookup via OpenStreetMap's Nominatim by default, with no API key - an optional Google Geocoding key can be supplied instead on the Mission page's Maps card Plus Codes and all lat/long conversion computed on-device AG Grid tables with searching, sorting, filtering and export No cookies, no accounts, no server: data stays in your browser's local storage Angular and Angular Material — the framework and the components almost everything on screen is built from AG Grid (Community edition) — the Rangers, Reports and Messages tables Leaflet , plus leaflet.offline — the Leaflet map engine and its offline tile saving MapLibre GL JS and PMTiles / Protomaps — the vector map engine and its bundled offline basemap format © OpenStreetMap contributors — the map data underneath both map engines OpenTopoMap (CC-BY-SA) — the topographic map style Esri — the hillshade (terrain relief) layer, the satellite imagery base map, and the roads and place names drawn over it Waymarked Trails (© waymarkedtrails.org, data © OpenStreetMap contributors, CC-BY-SA) — the hiking trails overlay Nominatim , OpenStreetMap's own geocoder — the default address lookup, no API key needed pdf-lib — fills the printable ICS-213 and ICS-309 forms fflate — the zip work behind mission backup/restore and bulk photo import SheetJS / xlsx — the grids' Excel export mgrs and utm — the MGRS and UTM coordinate conversions crypto-js — the optional passphrase encryption for backups and on-device storage" },
  { "tab": "about", "heading": "License", "anchor": "license", "text": "©2019– John Cornelison, under the GNU Affero General Public License v3 RangerTrak is free software: you can redistribute it and/or modify it under the terms of the GNU Affero General Public License as published by the Free Software Foundation, either version 3 of the License, or (at your option) any later version. Using RangerTrak — including at your EOC, exercise, or incident — is completely free and always will be. The license places no obligations at all on people who simply use the application. If you modify RangerTrak and distribute it, or run your modified version as a network service, you must make your modified source available under the same license. This program is distributed in the hope that it will be useful, but WITHOUT ANY WARRANTY; without even the implied warranty of MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE. See the license for details. Full text: https://www.gnu.org/licenses/agpl-3.0 Releases prior to this change were published under the MIT License and remain available under those terms." },
  { "tab": "feedback", "heading": "Contact us", "anchor": "contact-us", "text": "RangerTrak is a free, open-source project from SteadyEOC ( rangertrak.com ). There are two ways to reach us - pick the one that fits what you want to say: In public: the feedback form below, or the project on GitHub . It becomes a GitHub issue that anyone can read, and other users can add to. Best for a problem or an idea. In private: email RangerTrak@steadyeoc.com . Only the maintainer reads it. Best for anything with names, places or mission details, or that you'd rather not post. Not all feedback needs to become an issue - if you're unsure, describe what you saw and let the maintainer sort it. Feedback or an AAR (after-action review) note? Feedback goes to RangerTrak's developers right away, as a public GitHub issue, and needs a connection. An AAR note (the button at the top of every page) stays private on this device for your own team's after-action review. It works offline and is part of the mission backup. In the field with no signal, or no time? Press AAR note and mark it RangerTrak . Later, Review and send on the AAR notes page brings those notes here, for you to check before anything is sent. RangerTrak is free and will stay free. If it's useful to your team, you can support its development at buymeacoffee.com/JohnCornelison . That goes to the developer personally and isn't tax-deductible. Feedback helps just as much." },
  { "tab": "feedback", "heading": "Diagnostic log (optional)", "anchor": "diagnostic-log-optional", "text": "RangerTrak keeps a running record of what it did this session - useful when something goes wrong and you want to report it, or figure out why. Open the Log page The easiest way to include it is the Include a diagnostic report box on the feedback form above: press Preview to see exactly what would be added. It holds your version, browser and storage details and a short list of what the app did, and leaves out ranger names, report text and places. To keep a copy for yourself, press Copy diagnostics . For the full record, press Copy log to clipboard on the Log page and paste it into a private email rather than the public form." } ]
